export const STRIDE=6;const R=0,p=1,h=2,x=3,N=540;let o=[],t=null,i=0,u=0;export function startRecording(c){return o=c.map(e=>e.settings.position),o.includes("ball")||o.push("ball"),t=new Float32Array(o.length*6*540),i=0,u=0,o.slice()}function d(){if((i+1)*o.length*6<=t.length)return;const e=new Float32Array(t.length*2);e.set(t),t=e}export function record(c){if(!t)return;d();const e=i*o.length*6;t.fill(0,e,e+o.length*6);for(const n of c){const a=o.indexOf(n.settings.position);if(a===-1)continue;const s=e+a*6;t[s]=n.coords.x,t[s+1]=n.coords.y,t[s+2]=n.coords.z||0,t[s+3]=n.state&&n.state.xSpeed||0,t[s+4]=n.state&&n.state.ySpeed||0,t[s+5]=n.settings.benched?0:n.state&&n.state.hasBall?n.state.run?3:2:1}i+=1}export function frameCount(){return i}export function slotNames(){return o.slice()}export function frameAt(c,e){if(!t||i===0)return[];const a=Math.max(0,Math.min(i-1,Math.floor(c)))*o.length*6,s=[];for(let r=0;r<o.length;r+=1){const l=a+r*6,f=o[r];s.push({settings:{position:f,team:e?e(f):0,benched:t[l+5]===0},coords:{x:t[l],y:t[l+1],z:t[l+2]},state:{xSpeed:t[l+3],ySpeed:t[l+4],hasBall:t[l+5]===2||t[l+5]===3,run:t[l+5]===3}})}return s}export function focusAt(c){const e=frameAt(c),n=e.find(r=>r.state.hasBall&&!r.settings.benched);if(n)return n.coords;const a=e.find(r=>r.settings.position==="ball"&&!r.settings.benched);if(a&&(a.coords.x||a.coords.y))return a.coords;const s=e.find(r=>r.settings.position==="qb");return s?s.coords:{x:0,y:0,z:0}}export function rewind(){u=0}export function advance(c,e,n=1){return u+=c*e*n,u>=i}export function playheadFrame(){return u}export function isEmpty(){return i===0}export function discard(){t=null,o=[],i=0,u=0}
